import numpy as np
def fitk(k, kind):
    if kind=='eps': E=np.exp(-k*eps)
    if kind=='epsT': E=np.exp(-k*eps*T)
    if kind=='eps/T': E=np.exp(-k*eps/T)
    cols=[eps**i*T**j for i in range(2) for j in range(4)]+[eps*E*T**j for j in range(4)]+[E*T**j for j in range(4)]
    X=np.column_stack(cols); c=np.linalg.lstsq(X,sigma,rcond=None)[0]
    return np.mean((sigma-X@c)**2)/np.var(sigma)
